package main

import (
	"fmt"
	"strings"
)

type state int

const (
	method state = iota
	target
	version
	carriage
	done
)

func next(current state, b byte) state {
	switch {
	case current == method && b == ' ':
		return target
	case current == target && b == ' ':
		return version
	case current == version && b == '\r':
		return carriage
	case current == carriage && b == '\n':
		return done
	default:
		return current
	}
}

func main() {
	names := []string{"method", "target", "version", "carriage", "done"}
	current := method
	var transitions []string
	for i := 0; i < len("GET / HTTP/1.1\r\n"); i++ {
		updated := next(current, "GET / HTTP/1.1\r\n"[i])
		if updated != current {
			transitions = append(transitions, names[updated])
		}
		current = updated
	}
	fmt.Println(strings.Join(transitions, " "))
}

