package main

import (
	"fmt"
	"strings"
)

func trailers(raw string) map[string]string {
	values := map[string]string{}
	raw = strings.TrimPrefix(raw, "0\r\n")
	for _, line := range strings.Split(raw, "\r\n") {
		if line == "" {
			break
		}
		name, value, ok := strings.Cut(line, ":")
		if ok {
			values[name] = strings.TrimSpace(value)
		}
	}
	return values
}

func main() {
	values := trailers("0\r\nDigest: abc\r\nX-Trace: 42\r\n\r\n")
	fmt.Printf("Digest=%s X-Trace=%s\n", values["Digest"], values["X-Trace"])
}

